const C=window.SITE_CONFIG,D=window.COLLECTIONS,P=window.PRODUCTS;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const asset=n=>'assets/'+n;
const pic=(n,alt,cl='')=>`<img class="${cl}" src="${asset(n)}" alt="${esc(alt)}" loading="lazy" decoding="async">`;
const link=(label,url,cl='button')=>`<a class="${cl}" href="${url}">${label}</a>`;
const icon=(n)=>`<i class="fi fi-rr-${n}" aria-hidden="true"></i>`;
const sketch=`<svg class="bag-sketch" viewBox="0 0 240 220" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true"><path d="M44 78h152l17 122H27L44 78Z"/><path d="M78 95V47a42 42 0 0 1 84 0v48M86 78V47a34 34 0 0 1 68 0v31M44 78l17 122M196 78l-17 122M27 191h186"/><path stroke-dasharray="3 5" d="M53 85h134l15 106H38L53 85Z"/><circle cx="79" cy="90" r="3"/><circle cx="161" cy="90" r="3"/></svg>`;
const filename=location.pathname.split('/').pop()||'index.html',slug=filename.replace('.html',''),cat=D.find(d=>d.slug===slug);
document.title=cat?`${cat.title} | ${C.name}`:filename==='index.html'?C.title:`${C.pageTitles[slug]||C.name} | ${C.name}`;
document.querySelector('link[rel="icon"]').href=C.favicon;
document.querySelector('meta[name="description"]').content=C.description.replace('{name}',C.name);
function header(){return `<header><div class="container nav-wrap"><a class="brand" href="index.html" aria-label="${esc(C.name)} home"><img src="${C.logo}" alt=""><span>${esc(C.name)}</span><small>${esc(C.tagline)}</small></a><nav aria-label="Main navigation">${C.navigation.map(n=>n.url==='shop-all.html'?`<div class="nav-dropdown"><button class="nav-link dropdown-trigger" aria-expanded="false" aria-controls="collection-menu">${n.label}<svg viewBox="0 0 12 8" aria-hidden="true"><path d="m1 1 5 5 5-5"/></svg></button><div id="collection-menu" class="dropdown-panel" inert><span class="dropdown-caption">Find your everyday form</span>${D.map((d,i)=>`<a href="${d.slug}.html">${icon(['shopping-bag','bags-shopping','makeup-brush','wallet','luggage-rolling','apps'][i])}<span>${d.title}<small>${d.short}</small></span></a>`).join('')}</div></div>`:link(n.label,n.url,'nav-link')).join('')}</nav><div class="nav-actions"><button class="bag-toggle" aria-label="Open your selection">${icon('shopping-bag')}<span>Selection (<b class="bag-count">0</b>)</span></button><button class="menu-toggle" aria-label="Open navigation" aria-expanded="false"><span></span><span></span></button></div></div></header><div class="mobile-nav" inert>${C.navigation.map(n=>link(n.label,n.url,'')).join('')}<div class="mobile-categories">${D.map(d=>link(d.title,d.slug+'.html','')).join('')}</div><span>${esc(C.footer)}</span></div>`}
function footer(){return `<footer><div class="container"><div class="footer-top"><a class="brand" href="index.html"><img src="${C.logo}" alt=""><span>${esc(C.name)}</span></a><h2>${esc(C.footer)}</h2>${link('Explore the collection','shop-all.html','button light')}</div><div class="footer-grid"><div><h3>${esc(C.company)}</h3><p>Bags, accessories and a different perspective on the everyday.</p><a href="mailto:${esc(C.email)}">${esc(C.email)}</a>${C.address?`<p>${esc(C.address)}</p>`:''}</div><div><h3>Collections</h3>${D.map(d=>link(d.title,d.slug+'.html','')).join('')}</div><div><h3>Information</h3>${C.footerLinks.information.map(n=>link(esc(n.label),n.url,'')).join('')}</div><div><h3>The fine print</h3>${C.footerLinks.legal.map(n=>link(esc(n.label),n.url,'')).join('')}<button class="text-button" id="cookie-settings">Cookie settings</button></div></div><div class="footer-bottom"><p>${esc(C.disclaimer)}</p><span>© ${new Date().getFullYear()} ${esc(C.company)}<br><a href="https://www.flaticon.com/uicons" target="_blank" rel="noopener">Interface icons by Flaticon</a></span></div></div></footer>`}
function accordions(list){return `<div class="accordion">${list.map((x,i)=>`<details ${i===0?'open':''}><summary>${x[0]}<span aria-hidden="true">+</span></summary><div class="accordion-body"><p>${x[1]}</p></div></details>`).join('')}</div>`}
function collectionCards(){return `<div class="swiper collection-swiper"><div class="swiper-wrapper">${D.map((d,i)=>`<article class="swiper-slide collection-card"><a href="${d.slug}.html">${d.slug==='shop-all'?'<div class="collection-illustration">'+sketch+'</div>':pic(d.image,d.title)}<div class="card-content"><div class="card-top"><span>${d.size}</span><span>${d.use.split('&')[0]}</span></div><h3>${d.title}</h3><p>${d.desc}</p><span class="card-link">Explore collection</span></div></a></article>`).join('')}</div><div class="slider-footer"><span>Find a form for your everyday.</span><div class="slider-buttons"><button class="prev" aria-label="Previous collection">←</button><button class="next" aria-label="Next collection">→</button><button class="slider-pause" aria-label="Pause automatic slides" aria-pressed="false">Ⅱ</button></div></div></div>`}
function contact(){return `<section id="contact" class="section contact-section"><div class="container"><div class="contact-intro" data-aos="fade-up"><h2>${esc(C.collaborationTitle)}</h2><p>${esc(C.collaborationText)}</p></div><div class="contact-grid"><div class="contact-aside" data-aos="fade-right"><div class="contact-studio"><span class="contact-stamp">${esc(C.name)} / STUDIO DESK</span><h3>Let’s make<br>something of it.</h3><p>A considered purchase. An unexpected collaboration. A question worth asking.</p></div><div class="contact-sketch-wrap">${sketch}<span>A place for your ideas.</span></div><div class="contact-topics"><span>${icon('shopping-bag')} Product & order enquiries</span><span>${icon('link')} Partnerships & collaborations</span><span>${icon('comment-alt')} A little more information</span></div><div class="contact-bottom"><span>Write to the studio</span><a class="email-link" href="mailto:${esc(C.email)}">${esc(C.email)}</a><p>Tell us your idea, preferred piece or the details you need. We’ll take it from there.</p></div></div><form id="contact-form"><div class="form-heading"><h3>${esc(C.form.heading.replace('{name}',C.name))}</h3><span>All good things start here.</span></div><div class="form-row"><label>Your name<input name="name" autocomplete="name" placeholder="Full name" maxlength="100" required></label><label>Email address<input type="email" name="email" autocomplete="email" placeholder="you@example.com" maxlength="200" required></label></div><label>How can we help?<select name="subject" required><option value="">${esc(C.form.subjectPlaceholder)}</option>${C.form.subjects.map(subject=>`<option value="${esc(subject)}">${esc(subject)}</option>`).join('')}</select></label><label>Your message<textarea name="message" rows="4" maxlength="5000" placeholder="Tell us a little about what you are looking for…" required></textarea></label><div class="trap" aria-hidden="true"><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></div><label class="consent"><input type="checkbox" name="consent" required><span>I have read the <a href="privacy.html">Privacy Policy</a> and agree to the processing of my enquiry.</span></label><div class="form-send"><span>Thoughtfully received.<br>Personally considered.</span><button class="button dark" type="submit">${esc(C.form.submitLabel)}</button></div><p class="form-status" role="status" aria-live="polite"></p></form></div></div></section>`}
function home(){return `<main>
<section class="hero"><div class="hero-backdrop"></div><div class="container hero-inner"><div class="hero-meta"><span>AN EXPLORATION OF EVERYDAY FORM</span><span>BAGS / OBJECTS / ACCESSORIES</span></div><h1><span>Carry</span><span class="outline">something artful.</span></h1><img class="hero-bag" src="assets/hero-bag.avif" alt="Sculptural cognac leather tote bag" fetchpriority="high"><div class="hero-note"><span class="little-dot"></span><span>Beautiful form.<br>Everyday purpose.</span></div><div class="hero-bottom"><div><p>Considered bags and small objects.<br>For your day. For wherever comes next.</p>${link('Discover the collection','shop-all.html','button light')}</div><div class="hero-tags"><span>Everyday</span><span>Work</span><span>Travel</span></div></div><div class="hero-caption">THE ART OF CARRYING</div></div></section>
<section id="about" class="section"><div class="container about-composition" data-aos="fade-up"><div class="about-art"><div class="framed-copy"><h2 class="outline">Art in the<br>everyday.</h2><p>We see a bag as more than a place to put things. It is a shape you live with. An object you reach for. A small expression of who you are.</p><p>At ${esc(C.name)}, everyday utility meets a sculptural point of view. Explore bags and accessories for work, travel and everything in between.</p>${link('Find your form','shop-all.html','button light')}</div></div><div class="about-photo">${pic('editorial.avif','A sculptural bag and classical art in conversation')}<div><span>A considered collection.</span><strong>Made for your everyday.</strong></div></div><div class="about-values"><span>${icon('layers')} Considered shapes</span><span>${icon('briefcase')} Everyday purpose</span><span>${icon('world')} Room to explore</span></div></div></section>
<section id="collections" class="section collection-section"><div class="container"><div class="section-heading" data-aos="fade-up"><h2>Everyday <span class="outline dark-stroke">desire.</span></h2><p>Different shapes. Different routines.<br>One place to find what feels like you.</p></div>${collectionCards()}</div></section>
<section class="marquee-section" aria-label="Carry less ordinary"><div class="container marquee-shell"><div class="marquee-track">${Array(2).fill('<span>CARRY LESS ORDINARY</span><img src="assets/marquee-tote.svg" alt=""><span class="outline">FORM MEETS FUNCTION</span><img src="assets/marquee-wallet.svg" alt=""><span>EVERYDAY, CONSIDERED</span><img src="assets/marquee-pouch.svg" alt="">').join('')}</div></div></section>
<section class="section occasion-section"><div class="container"><div class="section-heading"><h2>A day, well carried.</h2><p>Start with the way you move.<br>Find the pieces that belong.</p></div><div class="occasion-grid">${[['The working day','Room for notebooks, essentials and a change of plans. Keep the working day together with a considered tote and a place for the smaller things.','Totes & organizers','tote-bags','briefcase','tote.avif'],['Out of office','Hands free. Plans open. Your essentials, always close. Find a compact shape that feels just right, from your morning coffee to an evening across town.','Crossbody & small objects','crossbody-bags','sun','crossbody.avif'],['A little further','Keep the little things in order, wherever you are heading. Gather cables, documents and daily rituals into pieces that make packing a little more considered.','Travel & cosmetic bags','travel-organizers','plane','organizer.avif']].map((x,i)=>`<article class="occasion-flip ${i===1?'dark-occasion':''}" tabindex="0" aria-label="${x[0]}. Press Enter to turn the card."><div class="occasion-turn"><div class="occasion-card occasion-front"><span class="occasion-symbol">${icon(x[4])}</span><h3>${x[0]}</h3><p>${x[1]}</p><div class="occasion-bottom"><span>${x[2]}</span><span>Turn to discover</span></div></div><a href="${x[3]}.html" class="occasion-back" tabindex="-1">${pic(x[5],x[0])}<span>${x[0]}<small>Explore the collection</small></span></a></div></article>`).join('')}</div></div></section>
<section class="section details-section"><div class="container details-grid"><div class="sculpture-frame" data-aos="fade-right">${pic('details-bag.avif','Ivory leather bag on a travertine plinth')}<span>A study in proportion.</span></div><div class="details-copy" data-aos="fade-left"><h2>Good design.<br>In every detail.</h2><p>A curve. A fold. A place for the things that matter. We bring the language of sculpture into the practical rhythm of everyday life.</p><div class="detail-line">${icon('ruler-combined')}<div><h3>A shape that fits</h3><p>Compare size, opening and capacity before choosing.</p></div></div><div class="detail-line">${icon('feather')}<div><h3>Materials in focus</h3><p>Explore texture, finish and care, with details confirmed for your chosen piece.</p></div></div><div class="detail-line">${icon('settings-sliders')}<div><h3>Purposeful details</h3><p>Think about closures, pockets and the way you carry.</p></div></div>${link('Explore all objects','shop-all.html','button dark')}</div></div></section>
<section class="section care-section"><div class="container care-panel"><div data-aos="fade-up"><h2 class="outline">Keep it beautiful.</h2><p>A few thoughtful habits go a long way. Find simple guidance for storing, cleaning and caring for the pieces you carry.</p><p>Empty your bag between busy days, give its shape a little support and take a moment to check the care instructions for its material. Small rituals help a favourite piece stay part of your everyday.</p><div class="care-actions">${link('Explore product care','product-care.html','button light')}<button class="button light" data-enquire="Product care advice">Ask about your piece</button></div></div><div class="care-sketch">${sketch}<span>Store gently. Carry often.</span></div></div></section>
<section class="section faq-section"><div class="container faq-grid"><div data-aos="fade-right"><h2>Good questions.</h2><p>A little clarity before you find your next everyday companion.</p>${link('Shipping & returns','shipping-returns.html','text-link')}${pic('faq-bag.avif','Sculptural black handbag','faq-cutout')}</div>${accordions([['How do I place an order?','Explore a collection and add an item to your selection. Send an order enquiry with your preferred colour and quantity. We will confirm the product details, availability, price and delivery options before you decide.'],['Where can I find dimensions?','Use the product details panel to review the available information. Exact dimensions and materials are confirmed with your enquiry; please include any size requirements.'],['Can I ask about a particular colour?','Of course. Tell us your preferred colour in the enquiry. We will confirm the options available for the item you have selected.'],['Do you welcome collaborations?','Yes. Use the Advertise & Collaborate form below to tell us about your audience, idea, timeline and budget.']])}</div></section>
${showcase()}${materialRail()}${inspirationSlider()}${homeMaterialStory()}${editorialStories()}${journal()}${contact()}</main>`}
function journal(){return `<section class="section journal-section"><div class="container journal-grid"><div class="journal-image">${pic('studio-journal.avif','Bags and small accessories on architectural plinths')}<span>The everyday composition</span></div><div class="journal-copy"><h2>Better together.</h2><p class="large-copy">A bag for the day.<br>A place for everything inside.</p><p>Build a small collection around your routine. Pair a generous tote with a pouch, keep your cards close, and give the things you carry a little more order.</p><div class="journal-pairings"><a href="tote-bags.html">The daily bag<span>Room for the bigger picture</span></a><a href="cosmetic-bags.html">The small companion<span>Everything in its place</span></a><a href="wallets-accessories.html">The finishing touch<span>Keep the essentials close</span></a></div>${link('Compose your everyday','shop-all.html','button dark')}</div></div></section>`}
function flipPhoto(d){return `<div class="category-art flip-photo" role="button" tabindex="0" aria-label="Turn ${d.title} image to read the collection tag" aria-pressed="false"><div class="photo-turn"><div class="photo-front">${pic(d.image,d.title)}<div class="photo-caption"><span>${d.short}</span><span class="turn-symbol" aria-hidden="true">${icon('rotate-right')}</span></div></div><div class="photo-back luxury-tag"><span class="tag-hole" aria-hidden="true"></span><div class="tag-brand"><span>${esc(C.name)}</span><small>${esc(C.tagline)}</small></div><div class="tag-title"><span>THE COLLECTION</span><h3>${d.title}</h3><p>${d.short}</p></div><dl class="tag-details"><div><dt>Material direction</dt><dd>${d.material}</dd></div><div><dt>Made for your</dt><dd>${d.use}</dd></div><div><dt>Colour palette</dt><dd>${d.colors.join(' / ')}</dd></div></dl><div class="tag-message">An everyday object.<br>A considered choice.</div><span class="tag-bottom">Explore the details with our studio.</span></div></div></div>`}
function productCard(p,active){return `<article class="product-card ${active?'is-selected':''}" data-select="${p.slug}" data-style="${p.style}" data-size="${p.size.toLowerCase()}" data-material="${p.materialKey}" data-use="${p.uses.join(' ')}" tabindex="0" aria-label="Explore ${p.name}"><div class="product-image"><div class="product-drawing">${sketch}<span>${p.short}</span></div>${pic(p.image,p.name)}<span class="product-badge">${p.size}</span><span class="selected-check" aria-hidden="true">${icon('check')}</span></div><div class="product-info"><span class="product-kind">${p.category}</span><h3><button class="product-title" data-select-product="${p.slug}">${p.name}</button></h3><p>${p.desc}</p><div class="product-facts"><span>${p.material}</span><span>${p.uses.join(' / ')}</span></div><div class="swatches" aria-label="Preferred colour">${p.colors.map((c,i)=>`<button type="button" title="${c}" aria-label="${c}" aria-pressed="${i===0}" data-colour="${c}" data-item="${p.slug}" style="--swatch:${p.swatches[i]}"></button>`).join('')}<small class="colour-name">${p.colors[0]}</small></div><div class="product-actions"><button class="button dark" data-add="${p.slug}">Add to selection</button><button class="text-button" data-product="${p.slug}">Quick view</button></div><div class="product-foot"><span>Price on enquiry</span><button class="text-button" data-story="${p.slug}">Explore the details</button></div></div></article>`}
function intentContent(p){return `<div class="intent-top"><span class="object-label">THE OBJECT IN FOCUS</span><span class="object-counter">${p.category}</span></div><h2>${p.name}.</h2><div class="intent-body"><p class="large-copy">${p.story}</p><div class="intent-detail"><span>${p.short}</span><p>${p.detail}</p><div class="intent-tags">${icon('palette')}<span>${p.colors.join(' / ')}</span></div></div></div>`}
function fitContent(p){return `<div class="fit-heading"><span class="object-label">A PLACE FOR YOUR EVERYDAY</span><h2>Find your fit.</h2><p>${p.fitIntro}</p></div><div class="fit-note-list">${p.notes.map((n,i)=>`<div class="fit-note">${icon(['ruler-combined','layers','check-circle'][i])}<span>${n}</span></div>`).join('')}</div><div class="fits-inside"><span>Think about what you carry</span><div>${p.carry.map(x=>`<b>${x}</b>`).join('')}</div></div><p class="small-copy">Exact measurements, composition and availability are confirmed before purchase.</p>`}
function colourPhoto(p,colour){return p.variantImages?.[Math.max(0,p.colors.indexOf(colour))]||p.image}
function fitVisual(p,colour=p.colors[0]){return `<div class="fit-photo-frame" data-mode="object">${pic(colourPhoto(p,colour),p.name+' in '+colour,'fit-photo-image')}<svg class="measurement-guide" viewBox="0 0 400 350" aria-hidden="true"><path d="M55 50v250m-7-250h14m-14 250h14M85 315h240m-240-7v14m240-14v14"/><text x="45" y="165" transform="rotate(-90 45 165)">HEIGHT</text><text x="180" y="338">WIDTH</text></svg><span class="fit-photo-label">${p.name} · ${colour}</span></div><div class="fit-photo-controls"><button data-fit-view="size">${icon('ruler-combined')} Size</button><button data-fit-view="material">${icon('layers')} Material</button><button data-fit-view="details">${icon('fingerprint')} Details</button></div><p id="fit-inspection-note" aria-live="polite">Explore the size, texture and details.</p>`}
function materialRail(d){const prefix=d?d.slug:'home';return `<section class="section materials-accordion" aria-label="Explore six material directions"><div class="container"><div class="material-rail">${window.MATERIALS.map((m,i)=>`<article class="material-leaf ${i===0?'expanded':''}" style="--material-image:url('${asset(m.image)}')"><button class="material-toggle" aria-expanded="${i===0}" aria-controls="${prefix}-material-${i}"><span>${m.name}</span><b aria-hidden="true">${i===0?'−':'+'}</b></button><div class="material-reveal" id="${prefix}-material-${i}" ${i===0?'':'inert'}><span>THE MATERIAL EDIT</span><h3>${m.line}</h3><p>${m.text}</p><button class="mail-button" data-enquire="${d?d.title+' / ':''}${m.name}" aria-label="Enquire about ${m.name}">${icon('envelope')}</button></div></article>`).join('')}</div><p class="material-caption">Six textures. A different feeling for every day. <span>Select a material to explore.</span></p></div></section>`}
function colourComparison(d){const index=D.findIndex(x=>x.slug===d.slug),p=P[index]||P[0],pairings=[[0,3,2],[1,3,2],[2,3,4],[3,2,1],[4,2,3],[5,1,3]][index]||[0,3,2];const scene=variant=>`<div class="comparison-scene">${pairings.map((n,i)=>`<figure class="comparison-object object-${i}">${pic(P[n].variantImages[variant],P[n].name+' in '+P[n].colors[variant])}<figcaption>${P[n].name}</figcaption></figure>`).join('')}</div>`;return `<section class="section colour-comparison" aria-label="Compare a ${d.title.toLowerCase()} edit in two colour palettes"><div class="container"><div class="comparison-stage" style="--reveal:50%"><div class="comparison-base">${scene(1)}</div><div class="comparison-overlay">${scene(0)}</div><span class="comparison-caption first">The original edit<small>${p.colors[0]} & complementary pieces</small></span><span class="comparison-caption second">Another perspective<small>${p.colors[1]} & complementary pieces</small></span><div class="comparison-divider"><span aria-hidden="true">↔</span></div><input type="range" min="0" max="100" value="50" aria-label="Reveal the original or alternate colour palette"></div><div class="comparison-note"><span>Same shapes. A different mood.</span><span>Drag to explore the full edit.</span></div></div></section>`}
function puzzleStory(d){const stories={
 'tote-bags':{title:'Room for your day.',images:['tote-ink.avif','tote-sand.avif'],head:['A generous shape','A considered pairing'],copy:['Space for notebooks, a daily pouch and the things that go wherever you go.','Start with the tote, then choose the small pieces that keep everything in place.'],body:'From a working morning to a slower afternoon, a tote follows the rhythm of your day. Explore shapes that balance an open, easy silhouette with a purposeful interior.',note:'Think about what you carry most often. We can help you compare the opening, handle length and format before you choose.'},
 'crossbody-bags':{title:'Close to you.',images:['crossbody-stone.avif','crossbody-chestnut.avif'],head:['Light on the move','Details within reach'],copy:['A compact silhouette for the essentials, with your hands free for the day ahead.','A thoughtful opening and a comfortable strap can make a small bag feel just right.'],body:'A coffee, a city walk, an evening that unfolds. Crossbody bags bring a little freedom to everyday plans, with a shape that stays comfortably close.',note:'Compare the space inside with your phone, wallet and keys. Ask about the strap range and closure before settling on your favourite.'},
 'cosmetic-bags':{title:'Small rituals, kept.',images:['pouch-sand.avif','pouch-ink.avif'],head:['A place for rituals','Easy to bring along'],copy:['Keep brushes, daily favourites and the little necessities together in one place.','A soft, considered format that moves from the bathroom shelf to your travel bag.'],body:'The smallest routines deserve a little order. Explore cosmetic pouches that give your daily essentials a place of their own, at home or away.',note:'Tell us about the bottles, brushes and products you carry. We can help you confirm capacity, lining and the right care for the finish.'},
 'wallets-accessories':{title:'The little essentials.',images:['wallet-oxblood.avif','card-sleeve.avif'],head:['Keep it simple','A personal detail'],copy:['A thoughtful home for the cards, notes and small essentials you reach for every day.','Choose a quiet neutral or a richer accent to bring a familiar routine a new feeling.'],body:'A fold, a pocket, a carefully chosen colour. Small accessories make everyday gestures feel more considered, without adding unnecessary bulk.',note:'Start with what you really use. Compare the closed format, card capacity and compartments to find a piece that fits naturally into your day.'},
 'travel-organizers':{title:'A place for the journey.',images:['organizer-slate.avif','organizer-sand.avif'],head:['Pack by purpose','Find it at a glance'],copy:['Separate cables, travel documents and everyday pieces into a more useful arrangement.','Give each group a place so the small things stay easy to find when plans change.'],body:'Good organization leaves more room for the journey. Explore practical formats for the pieces that travel with you, from a short commute to a few days away.',note:'Gather your essentials first. We can help you compare compartments and dimensions with the bag or suitcase you already carry.'},
 'shop-all':{title:'Find your own form.',images:['barrel-bag.avif','suede-hobo.avif'],head:['Different directions','One everyday edit'],copy:['Explore structured shapes, softer silhouettes and small objects with a distinct character.','Build a combination around your own routine, with colours and textures that belong together.'],body:'A collection is personal when every object has a reason to be there. Explore bags, wallets and accessories through shape, texture and the way you live.',note:'Choose the pieces that catch your eye, then ask the studio about the details. We will help you explore the right combination before you decide.'}
};const p=stories[d.slug];return `<section class="section puzzle-section"><div class="container puzzle-layout"><div class="puzzle-grid${C.motion?.enabled!==false&&!matchMedia('(prefers-reduced-motion: reduce)').matches&&'IntersectionObserver' in window?' puzzle-ready':''}" aria-label="${d.title} in detail"><figure class="puzzle-tile puzzle-image" style="--tile:0">${pic(p.images[0],d.title+' — first material direction')}</figure><article class="puzzle-tile puzzle-card" style="--tile:1">${icon('layers')}<h3>${p.head[0]}</h3><p>${p.copy[0]}</p></article><article class="puzzle-tile puzzle-card ink-tile" style="--tile:2">${icon('fingerprint')}<h3>${p.head[1]}</h3><p>${p.copy[1]}</p></article><figure class="puzzle-tile puzzle-image" style="--tile:3">${pic(p.images[1],d.title+' — alternate object and finish')}</figure></div><div class="puzzle-copy"><span class="puzzle-mark" aria-hidden="true">${icon('shopping-bag')}</span><h2>${p.title}</h2><p>${p.body}</p><p>${p.note}</p>${link('Explore the details','#pieces','button dark')}</div></div></section>`}

function inspirationSlider(d){const ideas=window.OBJECT_IDEAS;return `<section class="section inspiration-section"><div class="container inspiration-layout"><figure class="inspiration-photo">${pic(d?d.image:'suede-hobo.avif',d?d.title:'Suede shoulder bag on stone')}<figcaption>${d?d.short:'Everyday objects. New perspectives.'}</figcaption><div class="dot-motif" aria-hidden="true">${'<i></i>'.repeat(25)}</div></figure><div class="inspiration-copy"><h2>${d&&d.slug!=='shop-all'?'A closer look.':'More to discover.'}</h2><p>${d&&d.slug!=='shop-all'?'Notes on choosing, carrying and caring for '+d.title.toLowerCase()+'. A considered approach to your next everyday object.':'Explore more shapes, textures and colour directions. These are visual examples: ask the studio about the pieces that catch your eye.'}</p><div class="swiper inspiration-swiper"><div class="swiper-wrapper">${ideas.map((idea,i)=>{const text=d&&d.slug!=='shop-all'?serviceNote(d,i):idea.text;return `<article class="swiper-slide inspiration-card"><p>${text}</p><div class="inspiration-card-foot">${pic(idea.image,idea.name)}<div><h3>${d&&d.slug!=='shop-all'?['Shape & purpose','Your everyday edit','A point of colour','Carry with ease','A little more order','Keep it beautiful'][i]:idea.name}</h3><span>${d&&d.slug!=='shop-all'?d.title:idea.material}</span></div><button class="mail-button" data-enquire="${d?d.title+' / ':''}${idea.name}" aria-label="Contact the studio about ${idea.name}">${icon('envelope')}</button></div></article>`}).join('')}</div><div class="inspiration-controls"><div class="inspiration-pagination"></div><div class="slider-buttons"><button class="inspiration-prev" aria-label="Previous idea">←</button><button class="inspiration-next" aria-label="Next idea">→</button><button class="slider-pause" aria-label="Pause automatic slides" aria-pressed="false">Ⅱ</button></div></div></div></div></div></section>`}
function serviceNote(d,i){return [
 `A good choice starts with the way you use it. ${d.story} Take a moment to gather the things you carry most often, then think about the shape that would make that routine feel easier. The studio can help you confirm the measurements, opening and carrying options before you settle on a particular piece.`,
 `Less searching, more enjoying the day. ${d.notes[0]} A well-chosen ${d.title.toLowerCase().replace(/s$/,'')} should feel natural in your routine, with enough room for what matters and no unnecessary complication. Tell us what you usually carry and where the piece will go. We can discuss the practical details together before you make a decision.`,
 `Colour changes the way a familiar shape feels. The palette for this direction includes ${d.colors.join(', ')}. Consider the clothes, other accessories and moments it will sit alongside, whether you prefer a quiet neutral or a more expressive accent. Select a colour to preview the idea, then contact us to confirm the available finish and current options.`,
 `Comfort is often found in the details. ${d.notes[1]} Think about the length of a working day, the layers you wear and how often you reach into your bag. Small differences in the opening, handle or strap can change the experience. Ask the studio for the details that matter to you before choosing the form.`,
 `Give each small thing a considered place. ${d.notes[2]} A pouch, a wallet or a simple organizer can help separate the things that belong together, without making your daily carry complicated. Begin with your existing routine and add only what improves it. The studio can help you explore a combination of pieces and confirm sizes before you decide.`,
 `The pieces you carry deserve a little attention between journeys. ${d.care} Simple habits can help an object keep its shape and character: empty it regularly, store it thoughtfully and check its specific instructions before cleaning. If you are unsure about a material or finish, ask us first rather than guessing which treatment to use.`
 ][i]}
function showcase(){return `<section class="section object-showcase"><div class="container"><h2 class="outline">The next everyday.</h2><p>More shapes. More ways to make them your own.</p><div class="showcase-grid">${window.OBJECT_IDEAS.slice(0,4).map((p,i)=>`<article class="showcase-card ${i%2?'solid':''}">${pic(p.image,p.name)}<h3>${p.name}</h3><p>${p.text.split('. ').slice(0,2).join('. ')}.</p><button class="button ${i%2?'dark':'light'}" data-enquire="${p.name}">Explore this idea</button></article>`).join('')}</div></div></section>`}
function homeMaterialStory(){return `<section class="section material-section home-material-story"><div class="container material-panel"><figure class="material-photo">${pic('fabric-study.avif','Canvas weave and carefully stitched leather details')}<figcaption><span>Texture, considered.</span><span>${esc(C.name)} / MATERIAL NOTES</span></figcaption></figure><div class="material-list"><div><h2>Made of details.</h2><p>The way a surface catches the light. The line of a seam. The feel of a handle. Materials bring character to the everyday objects we carry.</p></div><div><h3>Find the right feeling</h3><p>Explore smooth and textured leather, natural canvas and soft textiles. Ask us about the exact finish, lining and care of a piece before making it part of your day.</p></div>${link('Explore the collection','shop-all.html','button light')}</div></div></section>`}
function editorialStories(){return `<section class="section editorial-stories"><div class="container stories-layout"><div class="stories-intro"><h2>Stories in<br>everyday form.</h2><p>A considered collection is more than a series of objects. It is a way to look at texture, proportion and the small routines that make up a day.</p><p>Explore a few ideas for choosing what to carry, creating a useful pairing and looking after the pieces you keep close.</p>${link('Explore the object edit','shop-all.html','button dark')}<div class="story-minis"><a href="product-care.html">${pic('hardware-study.avif','Leather strap and hardware detail')}<h3>The little details.</h3></a><a href="travel-organizers.html">${pic('organizer.avif','Travel organizer')}<h3>A place for everything.</h3></a></div></div><article class="story-feature">${pic('studio-journal.avif','Bags and accessories composed on architectural plinths')}<h3>Where form meets everyday life.</h3><p>Build around your routine: a bag with the right proportions, a place for loose essentials and a small object that makes it personal.</p>${link('Find your everyday','tote-bags.html','button dark')}</article></div></section>`}
function categoryCta(d){return `<section class="section category-cta"><div class="container"><div class="cta-frame"><span class="cta-note">A NOTE TO THE STUDIO</span><h2 class="outline">Your next everyday.</h2><p>Tell us which ${d.title.toLowerCase()} caught your eye. We’ll help you explore the colour, shape and details.</p><button class="button light" data-enquire="${d.title}">Let’s find your form</button></div></div></section>`}

function category(d){const all=d.slug==='shop-all',items=[...P].sort((a,b)=>Number(b.style===d.slug)-Number(a.style===d.slug)),p=items[0];return `<main class="category-page"><section class="category-hero section"><div class="container category-hero-grid"><div class="category-hero-copy"><a class="back-link" href="index.html#collections">Collections / ${d.title}</a><div class="hero-copy-rule"><span class="little-dot"></span><span>EVERYDAY OBJECTS, CONSIDERED</span></div><h1 class="reveal-title"><span class="hero-word">${d.title}</span></h1><p>${d.desc}</p><div class="hero-editorial-note"><span>${icon('fingerprint')}</span><p>${d.story}</p></div><div class="hero-dual-actions">${link(all?'Browse all objects':'Explore this collection','#pieces','button dark')}<button class="button secondary" data-enquire="${d.title}">Ask the studio</button></div><div class="category-meta"><span>${d.size}</span><span>${d.material}</span><span>${d.use}</span></div><div class="hero-footnote"><span>Shape / Texture / Purpose</span><span class="animated-thread" aria-hidden="true"></span></div></div>${flipPhoto(d)}</div></section>
${puzzleStory(d)}
<section id="pieces" class="section catalog-section"><div class="container"><div class="section-heading"><h2>${all?'Find your form.':'The object edit.'}</h2><p>Six considered objects. Start with a favourite.<br>Select a piece to explore its story and fit below.</p></div><div class="filters"><div class="filter-title">${icon('settings-sliders')}<span>Refine<br>your edit</span></div><label>Collection<select id="filter-style"><option value="all">All collections</option>${D.slice(0,5).map(x=>`<option value="${x.slug}">${x.title}</option>`).join('')}</select></label><label>Size<select id="filter-size"><option value="all">Every size</option><option>Small</option><option>Compact</option><option>Medium</option><option>Large</option></select></label><label>Material<select id="filter-material"><option value="all">All materials</option><option value="leather">Leather</option><option value="canvas">Canvas</option><option value="textiles">Textiles</option></select></label><label>Use<select id="filter-use"><option value="all">Every occasion</option><option value="everyday">Everyday</option><option value="work">Work</option><option value="travel">Travel</option></select></label><button class="reset-filters" id="reset-filters" aria-label="Reset all filters">${icon('rotate-left')}<span>Reset</span></button></div><div class="catalog-status"><span id="filter-count" role="status">6 objects</span><span>Choose a card. Discover its story.</span></div><div class="product-grid">${items.map((x,i)=>productCard(x,i===0)).join('')}</div><div id="empty-filter" hidden><h3>No objects in this edit.</h3><p>Try a different combination of size, material or occasion.</p><button class="button dark" id="empty-reset">Show all six objects</button></div><div class="selected-summary"><span id="selected-product-note" role="status">Now exploring: ${p.name}</span><a href="#product-story">Read the story below</a></div></div></section>
<section id="product-story" class="section intent-section"><div class="container intent-grid" data-active-product="${p.slug}">${intentContent(p)}</div></section>
<section class="section fit-section"><div class="container fit-grid"><div class="fit-drawing"><div id="fit-visual">${fitVisual(p)}</div><div class="fit-sketch-preserved">${sketch}</div><span id="fit-object-name">${p.name} / A study in proportion</span><div class="fit-drawing-notes"><span>Consider the opening</span><span>Keep your essentials in mind</span></div></div><div id="fit-content">${fitContent(p)}</div></div></section>
<section class="section material-section"><div class="container material-panel"><figure class="material-photo">${pic('accessory-study.avif','Leather accessories arranged on stone')}<figcaption><span>Texture, up close.</span><span>${esc(C.name)} / MATERIAL STUDY</span></figcaption></figure><div class="material-list"><div><span class="object-label">A CLOSER LOOK</span><h3>${d.material}</h3><p>Texture gives an object its character. Look at the grain, feel of the lining and finish of the details. We can help you confirm the composition of your chosen piece.</p></div><div><h3>Care for the details</h3><p>${d.care}</p><p>Choose a finish that belongs in your daily routine, and make a little room for care.</p></div>${link('Read the care guide','product-care.html','button light')}</div></div></section>
<section class="section category-faq"><div class="container faq-grid"><div class="category-faq-copy"><h2>Before you choose.</h2><p>A closer look at ${d.title.toLowerCase()}. From the way it feels to the things it holds, a few small details can make the difference.</p><div class="faq-help"><span>${icon('comment-alt')} A question about a particular piece?</span><button class="text-button" data-enquire="${d.title}">Ask the studio</button></div>${pic('studio-journal.avif','A considered collection of everyday bags','faq-horizontal')}</div>${accordions([['How do I confirm the size?',d.notes.join(' ')+' We will confirm exact measurements before you order.'],['Which colours are available?',`The concept palette includes ${d.colors.join(', ')}. Actual colours and availability will be confirmed individually.`],['How should I care for it?',d.care+' Check the specific product instructions before applying any cleaning product.'],['When will my order arrive?','Delivery destinations, costs and timing are confirmed with your enquiry before a purchase is agreed. See Shipping & Returns for the enquiry process.']])}</div></section>
${materialRail(d)}${colourComparison(d)}${inspirationSlider(d)}${categoryCta(d)}</main>`}
const policy={
'privacy':{title:'Privacy Policy',intro:'How information is handled when you explore our collection or send an enquiry.',sections:[['Information you provide','When you contact us, you may provide your name, email address, selected products and message. Please do not include payment details or sensitive information.'],['How we use it','Enquiry information is used to respond to your request, discuss product availability and manage any subsequent correspondence. It is not used to sign you up for marketing without your choice.'],['Storage and service providers','Hosting and email providers may process technical data and enquiry information to operate the website and deliver messages. Actual retention periods and provider details must be confirmed by the site operator before commercial launch.'],['Your choices','Contact the email address below to ask about your information, request correction or deletion, or raise a privacy concern. Any request is handled in accordance with the rules applicable to the operator.'],['Local website preferences','Your selection and cookie preference are stored in your browser. You can clear these through your browser settings. See our Cookie Policy for details.']]},
 'terms':{title:'Terms & Conditions',intro:'Please read this information before using the website or making an enquiry.',sections:[['About this collection','This website presents a concept collection of bags and accessories. Images are illustrative and do not establish actual stock, material composition, dimensions or availability.'],['Enquiries and orders','Submitting an enquiry does not create a binding purchase and no online payment is taken. Product details, final price, delivery and applicable return terms must be confirmed before any order is agreed.'],['Product information','We aim to describe the intended collection clearly. Colours may appear differently on screens. Ask for exact measurements, composition and current images before deciding.'],['Use of the website','Use this website lawfully. Do not submit misleading requests, malicious content or personal information belonging to others without permission.'],['Questions','Contact us through the form or email below if you need clarification. Applicable consumer rights are not excluded by these terms.']]},
 'cookies':{title:'Cookie Policy',intro:'A small amount of browser storage helps this site remember your choices.',sections:[['Essential preferences','The site stores your cookie preference under forma-consent and your product selection under forma-selection in localStorage. These values stay in your browser until cleared.'],['Analytics and advertising','This version does not install analytics or advertising cookies. Optional cookie choices are recorded, but do not activate any tracking.'],['Third-party services','The website is hosted by an external hosting provider. The hosting platform may use its own essential security or authentication mechanisms.'],['Changing your preference','Use Cookie settings in the footer to reopen the preference card. You can also delete local data in your browser settings.']]},
 'shipping-returns':{title:'Shipping & Returns',intro:'Clear details before you commit. Every order begins with a conversation.',sections:[['Before ordering','Send an enquiry with the selected item, colour, quantity and destination country. We will confirm availability, item specifications, total price and delivery options before you agree to purchase.'],['Shipping information','Shipping destinations, charges, dispatch dates, estimated transit times and tracking availability are confirmed individually. No fixed shipping price or delivery promise is made on this concept website.'],['Returns and exchanges','Ask for the return window, eligibility, return address and any return shipping costs before confirming your order. Your applicable statutory consumer rights remain unaffected.'],['If something is wrong','Contact us with your order reference and a description of the issue. Include relevant photos when requested. Do not send an item back until you have received the correct instructions.']]},
 'product-care':{title:'Product Care',intro:'Keep the pieces you carry looking their best. Always check the instructions for the specific item first.',sections:[['Leather','Remove surface dust with a soft dry cloth. Avoid soaking, direct heat and prolonged sunlight. Test any appropriate leather care product on a hidden area first.'],['Canvas and textiles','Brush off loose dirt gently. Spot-clean only if the product care instructions allow it. Do not machine wash unless explicitly stated on the label.'],['Hardware and zips','Wipe hardware with a soft cloth. Do not force a stuck zip; check for caught fabric and remove the obstruction gently.'],['Storage','Empty the bag, allow it to dry, and store it away from direct sunlight. Lightly support its shape with clean paper or fabric and avoid hanging heavy bags by their straps.'],['A note on finishes','Suede, coated fabrics and technical textiles can need different treatment. Ask us about the material before applying water, solvents or conditioners.']]}
};
policy.privacy.sections.push(
 ['Product selections','Your chosen products, quantities and preferred colours are saved locally in your browser. Adding a product to the selection does not by itself send an enquiry or create an order. These details are copied into the contact message when you choose to enquire.'],
 ['What happens to an enquiry','Once the contact service is connected, the information you submit is passed to the configured mail service. A successful confirmation means the server has accepted the request for delivery. If the service is unavailable, an error is shown instead; your form is not presented as successfully sent.'],
 ['Security and sensible sharing','The form validates the supplied email and required fields, includes an automated-submission check and limits repeated submissions on the PHP endpoint. Avoid including identity documents, passwords or payment card details in a message.'],
 ['Questions and corrections','To help us locate a previous enquiry, write from the same email address and include its approximate date and subject. Explain which details you would like to review or correct. Do not send sensitive documents unless they are specifically needed and an appropriate channel has been agreed.']
);
policy.terms.sections.push(
 ['Your selection','The selection list is a planning tool. You can add or remove products, change quantities and choose a preferred colour. Products are not reserved by adding them, and the list does not represent a confirmed order or an agreed price.'],
 ['Confirming the details','Before making a purchase, review the exact product, quantity, colour, material, measurements, total cost and delivery arrangements supplied by the operator. Raise any question or mismatch before agreeing to proceed.'],
 ['Availability and updates','The collection, imagery and descriptive information may be updated as the offering develops. Previously saved browser selections can therefore differ from the current collection. Ask for current details when returning to an earlier enquiry.'],
 ['Website availability','Individual features depend on your browser, connectivity and the availability of the hosting and mail services. If a request fails, the website will not treat it as a successful submission. You can try again later or use the displayed contact address once it has been configured.'],
 ['Partnership enquiries','Advertising and collaboration requests are discussed individually. A message through the website does not establish a partnership, booking or obligation to supply services. The scope, budget, deliverables and timing need to be agreed separately.']
);
policy.cookies.sections.push(
 ['Your product selection','The forma-selection value stores the product identifiers, preferred colours and quantities in your selection. It allows the list to remain available when moving between pages or returning in the same browser. It is not a payment record.'],
 ['Temporary enquiry drafts','When you choose to enquire about a product, a temporary forma-enquiry value is kept in sessionStorage. The contact page uses it to prefill your message and then removes that stored draft. You may edit the message before sending.'],
 ['What the preference buttons do','Essential only and Accept both record your choice locally. This version does not activate analytics or advertising when Accept is selected. Reopening Cookie settings lets you change the recorded preference.'],
 ['Clearing your browser data','Deleting this site’s local storage will remove the saved selection and cookie preference. The preference card will appear again on a later visit. Browser settings may also prevent storage, which can affect these convenience features.'],
 ['Fonts, images and icons','The site’s font, image and interface assets are included with the website files. They are not used here to create an advertising profile. Following an external link, such as an icon-credit link, takes you to a separate website with its own settings.']
);
policy['shipping-returns'].sections.push(
 ['Information for an accurate quote','Include the selected product, preferred colour, quantity and destination country. Mention any delivery deadline that matters to you so the available options can be discussed before you commit.'],
 ['Check the final arrangement','Review any confirmed shipping charge, delivery estimate and recipient details alongside the item price. Do not assume a shipping service, destination or delivery date is included until it has been expressly confirmed.'],
 ['Changing an enquiry','If you need to change the requested item, quantity or destination, contact us using the same email address and reference your earlier message. Changes to a confirmed purchase must be discussed with the operator.'],
 ['Preparing a return request','Keep your purchase confirmation and relevant packaging while you resolve an issue. Describe the item, the reason for contacting us and the outcome you are requesting. The operator will confirm the appropriate next steps and return details.']
);
policy['product-care'].sections.push(
 ['After a wet day','If an item becomes wet, remove its contents, gently blot surface moisture and let it dry naturally in a ventilated place. Do not use a radiator or hair dryer. Follow any item-specific guidance for sensitive materials.'],
 ['Colour transfer','Dark or strongly dyed fabrics can sometimes transfer colour to lighter surfaces, and light leather can pick up colour from clothing. Take extra care with new denim, damp fabrics and prolonged contact.'],
 ['Keeping the shape','Avoid forcing more into a bag than fits comfortably. Support structured shapes during storage without stretching the material, and keep heavy objects from pressing into the sides.'],
 ['When to ask first','If you are unsure about the material or finish, pause before using a cleaner or treatment. Share the product name and the care question with the studio so the relevant instructions can be confirmed.']
);

function information(p){return `<main class="information-page"><section class="section"><div class="container"><div class="legal-hero"><div><a class="back-link" href="index.html">Home / Information</a><h1>${p.title}</h1><p class="large-copy">${p.intro}</p></div><div class="legal-seal">${icon(slug==='privacy'?'shield-check':slug==='cookies'?'cookie':slug==='product-care'?'feather':'document-signed')}<span>${esc(C.name)}<small>THE DETAILS MATTER</small></span></div></div><div class="legal-intro-bar"><span>${icon('book-open-cover')} Clear information, considered decisions.</span><a href="index.html#contact">A question? Talk to the studio</a></div><div class="policy-layout"><aside class="legal-sidebar"><div class="sidebar-group"><h3>On this page</h3><nav aria-label="Page contents">${p.sections.map((s,i)=>`<a href="#policy-${i}">${s[0]}<span aria-hidden="true">·</span></a>`).join('')}</nav></div><div class="sidebar-group"><h3>The information desk</h3>${Object.entries(policy).map(([k,v])=>`<a class="${k===slug?'current':''}" href="${k}.html">${v.title}</a>`).join('')}</div><div class="sidebar-contact"><span>${esc(C.company)}</span><p>Need clarity on a detail?<br>We are here to help.</p><a href="mailto:${esc(C.email)}">${esc(C.email)}</a>${link('Contact the studio','index.html#contact','button dark')}</div></aside><div class="legal-articles">${p.sections.map((s,i)=>`<article id="policy-${i}"><div class="legal-article-heading"><span class="legal-mark" aria-hidden="true"></span><h2>${s[0]}</h2></div><p>${s[1]}</p></article>`).join('')}<div class="legal-endnote"><h3>A little more clarity?</h3><p>If anything here needs a closer explanation, send a note with the title of this page and the detail you would like us to clarify.</p>${link('Start a conversation','index.html#contact','text-link')}</div></div></div></div></section></main>`}
document.getElementById('app').innerHTML=header()+(cat?category(cat):policy[slug]?information(policy[slug]):home())+footer()+`<aside class="cookie-card" aria-label="Cookie preferences" hidden><div>${icon('cookie')}<p>Your privacy, considered.<small>Only essential browser storage. <a href="cookies.html">Read policy</a></small></p></div><button class="cookie-choice text-button" data-choice="essential">Essential only</button><button class="cookie-choice button dark" data-choice="accepted">Accept</button></aside><dialog id="product-dialog"><button class="dialog-close" aria-label="Close product details">×</button><div id="product-content"></div></dialog><dialog id="selection-dialog"><button class="dialog-close" aria-label="Close selection">×</button><h2>Your selection.</h2><p>Collect your favourites, then send an enquiry.</p><div id="selection-content"></div><button id="selection-enquire" class="button dark">Enquire about selection</button></dialog><div id="toast" role="status"></div><div class="page-transition" aria-hidden="true">${sketch}<span>${esc(C.name)}</span></div>`;
let selection;try{selection=JSON.parse(localStorage.getItem('forma-selection')||'[]');if(!Array.isArray(selection))selection=[];selection=selection.filter(s=>P.some(p=>p.slug===s.slug)).map(s=>({...s,qty:Math.max(1,Math.min(99,Number(s.qty)||1))}))}catch{selection=[]}
const productColours=Object.fromEntries(P.map(p=>[p.slug,p.colors[0]]));
const save=()=>{localStorage.setItem('forma-selection',JSON.stringify(selection));document.querySelectorAll('.bag-count').forEach(x=>x.textContent=selection.reduce((a,b)=>a+b.qty,0))};save();
const toast=s=>{const el=document.getElementById('toast');el.textContent=s;el.classList.add('shown');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('shown'),2400)};
function add(slug){const p=P.find(x=>x.slug===slug);if(!p)return;const colour=productColours[slug];let old=selection.find(x=>x.slug===slug&&x.colour===colour);if(old)old.qty=Math.min(99,old.qty+1);else selection.push({slug,colour,qty:1});save();toast(p.name+' · '+colour+' added to your selection')}
function enquire(s){sessionStorage.setItem('forma-enquiry',s);location.href='index.html#contact'}
function selectionView(){const wrap=document.getElementById('selection-content');wrap.innerHTML=selection.length?selection.map((s,i)=>{const p=P.find(x=>x.slug===s.slug);return `<div class="selection-row">${pic(colourPhoto(p,s.colour||p.colors[0]),p.name)}<div><h3>${p.name}</h3><span>${esc(s.colour||p.colors[0])} · Price on enquiry</span></div><label>Quantity<input type="number" min="1" max="99" value="${s.qty}" data-quantity="${i}"></label><button class="text-button" data-remove="${i}">Remove</button></div>`}).join(''):'<p class="empty-selection">Your selection is empty. Explore a collection to find your first piece.</p>';document.getElementById('selection-enquire').disabled=!selection.length}
document.querySelector('.bag-toggle').onclick=()=>{selectionView();document.getElementById('selection-dialog').showModal()};
function chooseProduct(id,scroll=false){const p=P.find(x=>x.slug===id);if(!p||!cat)return;const intent=document.querySelector('.intent-grid'),fit=document.getElementById('fit-content');intent.innerHTML=intentContent(p);intent.dataset.activeProduct=id;fit.innerHTML=fitContent(p);document.getElementById('fit-visual').innerHTML=fitVisual(p,productColours[id]);document.getElementById('fit-object-name').textContent=p.name+' / A study in proportion';document.getElementById('selected-product-note').textContent='Now exploring: '+p.name;document.querySelectorAll('.product-card').forEach(c=>{c.classList.toggle('is-selected',c.dataset.select===id);c.setAttribute('aria-label','Explore '+P.find(x=>x.slug===c.dataset.select).name+(c.dataset.select===id?', selected':''))});if(!reduce){[intent,fit].forEach(el=>{if(el.animate)el.animate([{opacity:.2,transform:'translateY(9px)'},{opacity:1,transform:'translateY(0)'}],{duration:370,easing:'ease-out'})})}if(scroll)document.getElementById('product-story').scrollIntoView({behavior:reduce?'instant':'smooth',block:'start'})}
function showProduct(id){const p=P.find(x=>x.slug===id);if(!p)return;document.getElementById('product-content').innerHTML=`<div class="product-modal-grid">${pic(colourPhoto(p,productColours[id]),p.name)}<div><span>${p.category}</span><h2>${p.name}</h2><p>${p.desc}</p><dl><dt>Preferred colour</dt><dd>${esc(productColours[id])}</dd><dt>Material direction</dt><dd>${p.material}. Exact composition and dimensions confirmed on enquiry.</dd><dt>Everyday purpose</dt><dd>${p.uses.join(' / ')}</dd><dt>Care</dt><dd>${p.care}</dd><dt>Price & availability</dt><dd>Confirmed before purchase</dd></dl><button class="button dark" data-add="${p.slug}">Add to selection</button><p class="small-copy">Illustrative concept image.</p></div></div>`;document.getElementById('product-dialog').showModal()}
document.addEventListener('click',e=>{let b=e.target.closest('[data-add]');if(b){add(b.dataset.add);return}b=e.target.closest('[data-enquire]');if(b){enquire(b.dataset.enquire);return}b=e.target.closest('[data-remove]');if(b){selection.splice(+b.dataset.remove,1);save();selectionView();return}b=e.target.closest('[data-product]');if(b){showProduct(b.dataset.product);return}b=e.target.closest('[data-colour]');if(b){productColours[b.dataset.item]=b.dataset.colour;const group=b.closest('.swatches');group.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));group.querySelector('.colour-name').textContent=b.dataset.colour;const product=P.find(p=>p.slug===b.dataset.item);const photo=b.closest('.product-card').querySelector('.product-image>img');photo.src=asset(colourPhoto(product,b.dataset.colour));photo.alt=product.name+' in '+b.dataset.colour;if(document.querySelector('.intent-grid')?.dataset.activeProduct===product.slug)document.getElementById('fit-visual').innerHTML=fitVisual(product,b.dataset.colour);return}b=e.target.closest('[data-story]');if(b){chooseProduct(b.dataset.story,true);return}b=e.target.closest('[data-select]');if(b)chooseProduct(b.dataset.select)});
