const detailSection=document.querySelector('.details-section');if(detailSection){const image=detailSection.querySelector('.sculpture-frame img'),caption=detailSection.querySelector('.sculpture-frame>span'),base=image.getAttribute('src');const images=['measure-study.avif','fabric-study.avif','hardware-study.avif'],captions=['A considered fit.','Texture, up close.','The details you reach for.'];let requested=0;function viewDetail(index){requested++;const request=requested;const target=index<0?base:asset(images[index]);const apply=()=>{if(request!==requested)return;image.src=target;caption.textContent=index<0?'A study in proportion.':captions[index];if(!reduce&&image.animate)image.animate([{opacity:.35},{opacity:1}],{duration:320});detailSection.querySelectorAll('.detail-line').forEach((line,i)=>line.classList.toggle('active',i===index))};if(typeof Image==='function'){const next=new Image();next.onload=apply;next.src=target}else apply()}detailSection.querySelectorAll('.detail-line').forEach((line,i)=>{line.tabIndex=0;line.setAttribute('role','button');line.setAttribute('aria-label','View '+captions[i]);line.addEventListener('pointerenter',()=>viewDetail(i));line.addEventListener('focus',()=>viewDetail(i));line.addEventListener('click',()=>viewDetail(i));line.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();viewDetail(i)}})});detailSection.addEventListener('pointerleave',()=>{if(!detailSection.contains(document.activeElement))viewDetail(-1)});detailSection.addEventListener('focusout',e=>{if(!detailSection.contains(e.relatedTarget))viewDetail(-1)})}
